def _getitem_axis(self, key, axis: int):
    key = item_from_zerodim(key)
    if is_iterator(key):
        key = list(key)

    labels = self.obj._get_axis(axis)
    key = labels._get_partial_string_timestamp_match_key(key)

    if isinstance(key, slice):
        self._validate_key(key, axis)
        return self._get_slice_axis(key, axis=axis)
    elif com.is_bool_indexer(key):
        return self._getbool_axis(key, axis=axis)
    elif is_list_like_indexer(key):

        # Convert various list-like indexers to a list of keys
        if isinstance(labels, ABCMultiIndex):
            if isinstance(key, (ABCSeries, np.ndarray)) and key.ndim <= 1:
                key = list(key)
            elif isinstance(key, ABCDataFrame):
                raise NotImplementedError(
                    "Indexing a MultiIndex with a DataFrame key is not implemented"
                )
            elif hasattr(key, "ndim") and key.ndim > 1:
                raise NotImplementedError(
                    "Indexing a MultiIndex with a multidimensional key is not implemented"
                )

            if isinstance(key, list) and all(isinstance(k, (int, np.integer)) for k in key):
                # If all keys are integers, we should not fall back to positional
                for k in key:
                    if k not in labels:
                        raise KeyError(f"{k} not in index")
                return self._getitem_iterable(key, axis=axis)

            if not isinstance(key, tuple) and len(key) and not isinstance(key[0], tuple):
                key = tuple([key])

        # Handling nested tuple or multi-selection
        if not (isinstance(key, tuple) and isinstance(labels, ABCMultiIndex)):
            if hasattr(key, "ndim") and key.ndim > 1:
                raise ValueError("Cannot index with multidimensional key")

            return self._getitem_iterable(key, axis=axis)

        if is_nested_tuple(key, labels):
            locs = labels.get_locs(key)
            indexer = [slice(None)] * self.ndim
            indexer[axis] = locs
            return self.obj.iloc[tuple(indexer)]

    # Fall through to direct lookup
    self._validate_key(key, axis)
    return self._get_label(key, axis=axis)
